/* Desktop only - existing hover animation */
@media (min-width: 768px) {
    selector {
        overflow: hidden !important;
    }
    selector::after {
        content: "";
        position: absolute;
        inset: 0;
        background: inherit;
        background-size: cover !important;
        background-position: center !important;
        transition: transform 0.4s ease;
        transform: scale(1);
        z-index: 0;
        pointer-events: none;
    }
    selector:hover::after {
        transform: scale(1.1);
    }
    selector > * {
        position: relative;
        z-index: 1;
    }
}

/* Mobile only - scroll-triggered animation */
@media (max-width: 767px) {
    .mobile-lift-banner {
        overflow: hidden !important;
        position: relative;
    }

    .mobile-lift-banner::before {
        content: "";
        position: absolute;
        inset: 0;
        background: inherit;
        background-size: cover !important;
        background-position: center !important;
        transition: transform 0.4s ease;
        transform: scale(1);
        z-index: 0;
        pointer-events: none;
    }

    .mobile-lift-banner.is-lifted::before {
        transform: scale(1.06);
    }

    .mobile-lift-banner > * {
        position: relative;
        z-index: 1;
    }
}

