/* FIERRO: features on mobile - client spec: 2x2 centred grid, 25px icons, Jost 500/9px titles, Jost 300/8px text, 30px gaps */
@media (max-width: 767px) {
    selector { padding: 0 10px 30px 10px !important; }
    selector > .e-con-inner { display: grid !important; grid-template-columns: auto auto; justify-content: center; column-gap: 40px !important; row-gap: 14px !important; width: 100% !important; max-width: 100% !important; padding: 0 !important; }
    selector > .e-con-inner > .elementor-widget-icon-box { width: auto !important; max-width: none !important; margin: 0 !important; }
    selector .elementor-icon-box-wrapper { display: flex !important; flex-direction: row !important; align-items: flex-start !important; text-align: left !important; gap: 6px; }
    selector .elementor-icon-box-icon { margin: 0 !important; flex: 0 0 25px; line-height: 0 !important; }
    selector .elementor-icon-box-icon .elementor-icon, selector .elementor-icon-box-icon svg, selector .elementor-icon-box-icon img { width: 25px !important; height: 25px !important; font-size: 25px !important; line-height: 0 !important; }
    selector .elementor-icon-box-content { text-align: left !important; }
    selector .elementor-icon-box-title, selector .elementor-icon-box-title a { margin: 0 !important; font-family: 'Jost', sans-serif !important; font-weight: 500 !important; font-size: 9px !important; color: #000000 !important; letter-spacing: 0 !important; line-height: 1.3 !important; white-space: nowrap; }
    selector .elementor-icon-box-description { margin: 0 !important; font-family: 'Jost', sans-serif !important; font-weight: 300 !important; font-size: 8px !important; color: #6d6e71 !important; line-height: 1.3 !important; }
